import threading


# Unsafe, the bug
class Counter:
    def __init__(self):
        self.count = 0

    def increment(self):
        self.count += 1  # read-modify-write, not atomic


# Fixed, an explicit lock guards the critical section
class SafeCounter:
    def __init__(self):
        self.count = 0
        self.lock = threading.Lock()

    def increment(self):
        with self.lock:  # the lock is released automatically, even on exception
            self.count += 1

    def get(self):
        with self.lock:
            return self.count


if __name__ == "__main__":
    safe_counter = SafeCounter()

    def task():
        for _ in range(10000):
            safe_counter.increment()

    t1 = threading.Thread(target=task)
    t2 = threading.Thread(target=task)
    t1.start(); t2.start()
    t1.join(); t2.join()

    print(f"Expected 20000, got: {safe_counter.get()}")

