import java.util.concurrent.locks.ReentrantLock;

// Unsafe, the bug
class Counter {
    private int count = 0;
    void increment() { count++; }  // read-modify-write, not atomic
    int get() { return count; }
}

// Fixed, synchronized keyword acquires the object's intrinsic lock
class SafeCounter {
    private int count = 0;
    synchronized void increment() { count++; }
    synchronized int get() { return count; }
}

// Equivalent with an explicit lock, more control, must unlock manually
class SafeCounterExplicit {
    private int count = 0;
    private final ReentrantLock lock = new ReentrantLock();
    void increment() {
        lock.lock();
        try { count++; } finally { lock.unlock(); }  // finally guarantees unlock
    }
    int get() { return count; }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        SafeCounter safeCounter = new SafeCounter();
        Runnable task = () -> {
            for (int i = 0; i < 10000; i++) safeCounter.increment();
        };

        Thread t1 = new Thread(task);
        Thread t2 = new Thread(task);
        t1.start(); t2.start();
        t1.join(); t2.join();

        System.out.println("Expected 20000, got: " + safeCounter.get());
    }
}

