#include <bits/stdc++.h>
using namespace std;

// Unsafe, the bug
class Counter {
    int count = 0;
public:
    void increment() { count++; }  // read-modify-write, not atomic
    int get() { return count; }
};

// Fixed, std::mutex guards the critical section
class SafeCounter {
    int count = 0;
    mutex mtx;
public:
    void increment() {
        lock_guard<mutex> guard(mtx);  // released automatically when guard goes out of scope
        count++;
    }
    int get() {
        lock_guard<mutex> guard(mtx);
        return count;
    }
};

int main() {
    SafeCounter safeCounter;
    auto task = [&]() {
        for (int i = 0; i < 10000; i++) safeCounter.increment();
    };

    thread t1(task);
    thread t2(task);
    t1.join();
    t2.join();

    cout << "Expected 20000, got: " << safeCounter.get() << endl;
    return 0;
}

