import multiprocessing
import threading


# Python's standard library doesn't have a true lock-free CAS-based atomic int
# for threads; multiprocessing.Value provides the closest built-in equivalent,
# an integer with its own internal lock, used here across threads for demonstration
class AtomicCounter:
    def __init__(self):
        self._value = multiprocessing.Value("i", 0)

    def increment(self):
        with self._value.get_lock():
            self._value.value += 1

    def get(self):
        return self._value.value


if __name__ == "__main__":
    counter = AtomicCounter()

    def task():
        for _ in range(10000):
            counter.increment()

    t1 = threading.Thread(target=task)
    t2 = threading.Thread(target=task)
    t1.start(); t2.start()
    t1.join(); t2.join()

    print(f"Expected 20000, got: {counter.get()}")

