import threading


# Python's standard library has no built-in reader-writer lock,
# this is the standard textbook technique to build one from a plain Lock
class ReadWriteLock:
    def __init__(self):
        self._read_ready = threading.Condition(threading.Lock())
        self._readers = 0

    def acquire_read(self):
        with self._read_ready:
            self._readers += 1

    def release_read(self):
        with self._read_ready:
            self._readers -= 1
            if self._readers == 0:
                self._read_ready.notify_all()

    def acquire_write(self):
        self._read_ready.acquire()
        while self._readers > 0:
            self._read_ready.wait()

    def release_write(self):
        self._read_ready.release()


class ConfigCache:
    def __init__(self):
        self.data = {}
        self.rw_lock = ReadWriteLock()

    def get(self, key):
        self.rw_lock.acquire_read()  # many readers can hold this simultaneously
        try:
            return self.data.get(key)
        finally:
            self.rw_lock.release_read()

    def set(self, key, value):
        self.rw_lock.acquire_write()  # exclusive, blocks all readers and writers
        try:
            self.data[key] = value
        finally:
            self.rw_lock.release_write()


if __name__ == "__main__":
    cache = ConfigCache()
    cache.set("timeout", "30s")
    print(f"timeout = {cache.get('timeout')}")

