#include <bits/stdc++.h>
using namespace std;

class ConfigCache {
    unordered_map<string, string> data;
    shared_mutex rwLock;
public:
    string get(const string& key) {
        shared_lock<shared_mutex> lock(rwLock);  // many readers can hold this simultaneously
        auto it = data.find(key);
        return it != data.end() ? it->second : "";
    }

    void set(const string& key, const string& value) {
        unique_lock<shared_mutex> lock(rwLock);  // exclusive, blocks all readers and writers
        data[key] = value;
    }
};

int main() {
    ConfigCache cache;
    cache.set("timeout", "30s");
    cout << "timeout = " << cache.get("timeout") << endl;
    return 0;
}

