class Money:
    __slots__ = ("_cents", "_currency")

    def __init__(self, cents, currency):
        # Python has no real "final" fields; the convention (leading underscore,
        # no setters) is what communicates immutability instead
        self._cents = cents
        self._currency = currency

    @property
    def cents(self):
        return self._cents

    @property
    def currency(self):
        return self._currency

    def add(self, other):
        return Money(self._cents + other._cents, self._currency)  # returns new instance


# no setter for cents, nothing to race on

if __name__ == "__main__":
    a = Money(500, "USD")
    b = Money(250, "USD")
    total = a.add(b)
    print(f"{total.cents} {total.currency}")

