#include <bits/stdc++.h>
using namespace std;

// Immutable, const fields, no setters, safe to share across any number of threads
class Money {
    const long cents;
    const string currency;
public:
    Money(long cents, string currency) : cents(cents), currency(currency) {}

    Money add(const Money& other) const {
        return Money(cents + other.cents, currency); // returns new instance
    }
    // no setCents(), nothing to race on

    long getCents() const { return cents; }
    string getCurrency() const { return currency; }
};

int main() {
    Money a(500, "USD");
    Money b(250, "USD");
    Money total = a.add(b);
    cout << total.getCents() << " " << total.getCurrency() << endl;
    return 0;
}
